package com.bibliotech.fine.entity;import jakarta.persistence.*;import java.math.*;@Entity public class Fine{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)Long id;@Column(unique=true)Long rentalId;Long userId;int daysOverdue;BigDecimal fineAmount;String status="CALCULATED";public Long getId(){return id;}public Long getRentalId(){return rentalId;}public void setRentalId(Long v){rentalId=v;}public Long getUserId(){return userId;}public void setUserId(Long v){userId=v;}public int getDaysOverdue(){return daysOverdue;}public void setDaysOverdue(int v){daysOverdue=v;}public BigDecimal getFineAmount(){return fineAmount;}public void setFineAmount(BigDecimal v){fineAmount=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}}
